const s = $input.first().json;
if (typeof s.canonicalOrigin !== 'string' || !/^https:\/\/[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$/i.test(s.canonicalOrigin) || /\.(local|internal|localhost)$/i.test(s.canonicalOrigin)) throw new Error('Use a public HTTPS origin without a path, port, credentials or query.');
if (!Array.isArray(s.paths) || s.paths.length < 1 || s.paths.length > 10 || s.paths.some(p => typeof p !== 'string' || !p.startsWith('/') || p.startsWith('//') || /[?#\\\s]/.test(p))) throw new Error('Use 1–10 existing public paths starting with /, without query, fragment, backslash or whitespace.');
if (new Set(s.paths).size !== s.paths.length) throw new Error('Remove duplicate paths.');
const existingRunId = (s.existingRunId || '').trim();
if (existingRunId && !/^[A-Za-z0-9]{17}$/.test(existingRunId)) throw new Error('Existing run ID must have 17 letters or digits.');
if (!existingRunId && s.acknowledgePaidRun !== true) throw new Error('Review the USD0.16 run cap, select your Apify credential, then set acknowledgePaidRun to true.');
return [{json:{canonicalOrigin:s.canonicalOrigin,paths:s.paths,existingRunId,expectedChecks:s.paths.length*8,maxTotalChargeUsd:0.16}}];

const r=$input.first().json.data;
if (!r || !/^[A-Za-z0-9]{17}$/.test(r.id || '')) throw new Error('Invalid run response; inspect Apify Console before starting again.');
if (r.actId !== 'bk0IjVADsctt3rrXA') throw new Error('Saved run is not from the redirect checker.');
if (r.status === 'SUCCEEDED') return [{json:{runId:r.id,complete:true,run:r}}];
if (!['READY','RUNNING'].includes(r.status) || $runIndex >= 5) throw new Error('Run '+r.id+' is '+r.status+'. Inspect that run in Apify Console; do not start another paid run to recover it.');
return [{json:{runId:r.id,complete:false}}];

const s=$('Read completion summary').first().json;
const settings=$('Validate settings').first().json;
const rows=$input.first().json.body;
if (!Array.isArray(rows) || s.plannedChecks !== settings.expectedChecks || s.outputChecks !== rows.length || rows.length !== settings.expectedChecks || s.stoppedForTime || s.stoppedForBudget) throw new Error('Incomplete or mismatched results. Inspect the saved run; this is not a passing report.');
if (rows.some(r=>!['pass','review','fail','unknown'].includes(r.verdict))) throw new Error('Unrecognized result verdict.');
const counts={pass:0,review:0,fail:0,unknown:0};
for (const r of rows) counts[r.verdict]++;
for (const k of Object.keys(counts)) if ((s.verdicts?.[k] || 0) !== counts[k]) throw new Error('Summary and rows disagree.');
return [{json:{runId:$('Check run status').last().json.runId,complete:true,allChecksPassed:counts.pass===rows.length,counts,scope:'HTTP redirect observations only, not SEO health or analytics attribution.',checks:rows}}];
